arguments.command:
python3 -c "
import csv
with open('hospital_compensation_registry.csv') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

reasons = {}
for r in rows:
    reason = r['compensation_reason']
    if reason:
        reasons.setdefault(reason, []).append(float(r['direct_payment_usd']))

for reason, vals in reasons.items():
    print(reason, len(vals), min(vals), max(vals), sum(vals)/len(vals))
"

